mapper.update:
UPDATE schedule s
JOIN pet p ON s.pet_seq = p.pet_seq
SET
	s.title = #{title},
	s.schedule_time = #{scheduleTime},
	s.memo = #{memo},
	s.status = #{status},
	s.notify_enabled = #{notifyEnabled}
WHERE s.schedule_seq = #{scheduleSeq}
	AND p.user_seq = #{userSeq}

mapper.delete:
DELETE s
FROM schedule s
JOIN pet p ON s.pet_seq = p.pet_seq
WHERE s.schedule_seq = #{scheduleSeq}
	AND p.user_seq = #{userSeq}

mapper.select:
SELECT s.*
FROM schedule s
JOIN pet p ON s.pet_seq = p.pet_seq
WHERE s.schedule_seq = #{scheduleSeq}
	AND p.user_seq = #{userSeq}
